	if added != 3 {
		t.Errorf("expected 3 added, got %d", added)
	}
	if removed != 2 {
		t.Errorf("expected 2 removed, got %d", removed)
	}

	// Estimate modified lines: min(3, 2) = 2 modified
	// humanModified = 2
	// humanAdded = 3 - 2 = 1 (pure additions)
